using Microsoft.EntityFrameworkCore;
namespace DeliveryGo.Restaurants;
public sealed class Restaurant{public Guid Id{get;set;} public string Nombre{get;set;}="";public string Descripcion{get;set;}="";public string Categoria{get;set;}="";public string Direccion{get;set;}="";public string Imagen_url{get;set;}="";public bool Activo{get;set;}=true;public DateTime Fecha_creacion{get;set;}=DateTime.UtcNow;}
public sealed class RestaurantDb(DbContextOptions<RestaurantDb> options):DbContext(options){public DbSet<Restaurant> Restaurants=>Set<Restaurant>();protected override void OnModelCreating(ModelBuilder b){var e=b.Entity<Restaurant>();e.ToTable("restaurantes",t=>t.HasCheckConstraint("ck_restaurantes_categoria","categoria IN ('POLLERIA','CHIFA')"));e.HasKey(x=>x.Id);e.Property(x=>x.Id).HasColumnName("id");e.Property(x=>x.Nombre).HasColumnName("nombre").HasMaxLength(140).IsRequired();e.Property(x=>x.Descripcion).HasColumnName("descripcion").HasMaxLength(500).IsRequired();e.Property(x=>x.Categoria).HasColumnName("categoria").HasMaxLength(20).IsRequired();e.Property(x=>x.Direccion).HasColumnName("direccion").HasMaxLength(180).IsRequired();e.Property(x=>x.Imagen_url).HasColumnName("imagen_url").HasMaxLength(500).IsRequired();e.Property(x=>x.Activo).HasColumnName("activo");e.Property(x=>x.Fecha_creacion).HasColumnName("fecha_creacion");}}
public static class RestaurantSeed{public static async Task SeedAsync(RestaurantDb db){string[] names=["Pollería El Buen Sabor","Pollería Brasas Doradas","Pollería La Leña","Chifa Dragón Dorado","Chifa Palacio Oriental","Chifa Gran Muralla"];string[] desc=["Pollo a la brasa jugoso, con el toque casero que reúne a todos.","Tradición a las brasas, papas doradas y sabor para compartir.","Leña, fuego lento y ese aroma irresistible de siempre.","Clásicos orientales preparados al momento con sabor peruano.","Recetas abundantes que combinan tradición y frescura.","Un encuentro de sabores orientales para toda la familia."];string[] imgs=["photo-1598103442097-8b74394b95c6","photo-1626082927389-6cd097cdc6ec","photo-1532550907401-a500c9a57435","photo-1512058564366-18510be2db19","photo-1603133872878-684f208fb84b","photo-1563245372-f21724e3856d"];var rows=Enumerable.Range(0,6).Select(i=>new Restaurant{Id=Guid.Parse($"10000000-0000-4000-8000-{i+1:000000000000}"),Nombre=names[i],Descripcion=desc[i],Categoria=i<3?"POLLERIA":"CHIFA",Direccion="Lima, Perú",Imagen_url=$"https://images.unsplash.com/{imgs[i]}?auto=format&fit=crop&w=1200&q=85",Fecha_creacion=DateTime.UtcNow}).ToArray();var existing=await db.Restaurants.Select(x=>x.Id).ToListAsync();db.Restaurants.AddRange(rows.Where(r=>!existing.Contains(r.Id)));await db.SaveChangesAsync();}}
